#!/usr/bin/env node

// Stage 3 of the azure provider build: inject "supplemental" services -
// Azure services with NO azure-sdk-for-python package - from committed,
// proven service docs generated by the original AutoRest pipeline
// (ref/stackql-provider-azure-original, built from Azure/azure-rest-api-specs).
//
// MUST run after every stage-2 run: generate-provider.mjs wipes each
// provider tree and fully rewrites provider.yaml, removing stage-3 output.
// Re-running stage 3 alone is safe (idempotent): injected service docs carry
// an `info.x-stackql-supplemental: true` marker that authorizes overwrite,
// and the provider.yaml patch is a keyed insert + alphabetical re-sort.
//
// Hard-fail guards keep ownership honest:
//   - alias has a stage-1 source file  -> SDK coverage arrived; retire the
//     supplemental entry and artifact.
//   - alias already emitted (service yaml or providerServices entry) WITHOUT
//     the marker -> stage 2 owns it; refuse to clobber.

import fs from 'node:fs';
import path from 'node:path';
import { parseArgs } from 'node:util';
import {
  loadYaml,
  dumpYaml,
  derefSchema,
  resolveOperation,
  verifySignatureUniqueness,
  NAME_INFERRED,
} from './lib/common.mjs';

const scriptDir = path.dirname(
  new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')
);
const baseDir = path.resolve(scriptDir, '..');

const args = parseArgs({
  options: {
    config: { type: 'string', default: path.join(baseDir, 'config', 'supplemental-services.json') },
    'supplemental-dir': { type: 'string', default: path.join(baseDir, 'supplemental') },
    'output-dir': { type: 'string', default: path.join(baseDir, 'openapi', 'src') },
    'source-dir': { type: 'string', default: path.join(baseDir, 'source') },
    version: { type: 'string', default: 'v00.00.00000' },
    // Contingency for the v0.10.542 local-registry schema resolution bug
    // (schemaRef is a cousin of the banned schema_override; path-level
    // response schemas carry identical $refs, so stripping is safe).
    'strip-schema-ref': { type: 'boolean', default: false },
  },
}).values;

const configPath = path.resolve(args.config);
const supplementalDir = path.resolve(args['supplemental-dir']);
const outputBase = path.resolve(args['output-dir']);
const sourceDir = path.resolve(args['source-dir']);
const version = args.version;

const fail = (msg) => {
  console.error(`  FAIL  ${msg}`);
  process.exit(1);
};

if (!fs.existsSync(configPath)) {
  console.log(`No supplemental config at ${configPath} - nothing to do`);
  process.exit(0);
}
const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
const services = config.services || {};
const aliases = Object.keys(services).sort();
if (!aliases.length) {
  console.log('Supplemental config has no services - nothing to do');
  process.exit(0);
}

console.log(`Injecting ${aliases.length} supplemental services from ${supplementalDir}`);

const isSupplementalDoc = (p) => {
  try {
    const doc = loadYaml(p);
    return !!(doc && doc.info && doc.info['x-stackql-supplemental']);
  } catch {
    return false;
  }
};

// All provider trees stage 2 may have emitted (guard scan needs every tree,
// not just the target one).
const allProviderDirs = fs.existsSync(outputBase)
  ? fs.readdirSync(outputBase).filter((d) => fs.existsSync(path.join(outputBase, d, version, 'provider.yaml')))
  : [];

let injected = 0;
const providerYamlCache = {};

for (const alias of aliases) {
  const meta = services[alias] || {};
  const provider = meta.provider;
  if (!provider) fail(`[${alias}] supplemental entry has no 'provider'`);

  const artifactPath = path.join(supplementalDir, `${alias}.yaml`);
  if (!fs.existsSync(artifactPath)) {
    fail(`[${alias}] missing artifact ${artifactPath}`);
  }

  // Guard 1: SDK coverage arrived - the SDK pipeline owns this alias now.
  const sdkSource = path.join(sourceDir, `${alias}.yaml`);
  if (fs.existsSync(sdkSource)) {
    fail(
      `[${alias}] a stage-1 source file exists (${sdkSource}) - SDK coverage has arrived; ` +
        `retire the supplemental entry and artifact, the SDK pipeline owns this service now.`
    );
  }

  // Guard 2: stage 2 emitted this alias (any provider tree) without the marker.
  for (const pd of allProviderDirs) {
    const emitted = path.join(outputBase, pd, version, 'services', `${alias}.yaml`);
    if (fs.existsSync(emitted) && !isSupplementalDoc(emitted)) {
      fail(`[${alias}] ${emitted} exists and is not stage-3 output - stage 2 owns this alias, refusing.`);
    }
  }

  const providerYamlPath = path.join(outputBase, provider, version, 'provider.yaml');
  if (!fs.existsSync(providerYamlPath)) {
    fail(`[${alias}] ${providerYamlPath} not found - run stage 2 (generate-provider.mjs) first.`);
  }
  const providerYaml = (providerYamlCache[provider] =
    providerYamlCache[provider] || loadYaml(providerYamlPath));

  // Guard 3: providerServices already has the alias but the on-disk service
  // doc is not marked supplemental (or is missing) - not ours to replace.
  const existingEntry = (providerYaml.providerServices || {})[alias];
  if (existingEntry) {
    const emitted = path.join(outputBase, provider, version, 'services', `${alias}.yaml`);
    if (!fs.existsSync(emitted) || !isSupplementalDoc(emitted)) {
      fail(`[${alias}] provider.yaml already lists this service and it is not stage-3 output, refusing.`);
    }
  }

  const spec = loadYaml(artifactPath);

  // ----- validation -----
  if (!/^3\.0/.test(String(spec.openapi || ''))) {
    fail(`[${alias}] artifact is not OpenAPI 3.0.x (openapi: ${spec.openapi})`);
  }
  const resources = (spec.components && spec.components['x-stackQL-resources']) || {};
  if (!Object.keys(resources).length) {
    fail(`[${alias}] artifact has no components/x-stackQL-resources`);
  }

  let viewCount = 0;
  for (const [rName, r] of Object.entries(resources)) {
    const isView = !!(r.config && r.config.views && r.config.views.select);
    const methodNames = Object.keys(r.methods || {});
    if (isView && !methodNames.length) {
      viewCount++;
      continue;
    }
    if (!methodNames.length) {
      fail(`[${alias}] resource ${rName} has no methods and is not a view`);
    }
    // Every method's operation $ref must resolve to a real path operation.
    for (const [mName, m] of Object.entries(r.methods)) {
      if (!resolveOperation(spec, m)) {
        fail(`[${alias}] ${rName}.${mName} operation $ref does not resolve to a path operation`);
      }
    }
    // stackql name-inference guard: a method literally named get/list/... that
    // is NOT in its inferred sqlVerbs bucket must be renamed <name>_raw
    // (expected no-op on the proven artifacts - fixing rather than failing
    // keeps future artifacts usable).
    for (const [name, verbKey] of Object.entries(NAME_INFERRED)) {
      if (!r.methods[name]) continue;
      const inBucket = (r.sqlVerbs && r.sqlVerbs[verbKey] ? r.sqlVerbs[verbKey] : []).some(
        (ref) => ref.$ref.split('/').pop() === name
      );
      if (!inBucket) {
        const nn = `${name}_raw`;
        if (!r.methods[nn]) r.methods[nn] = r.methods[name];
        delete r.methods[name];
        console.log(`  note  ${alias}.${rName}.${name} -> ${nn} (name-inference guard)`);
      }
    }
    // Every sqlVerbs $ref must point at an existing method.
    for (const [verbKey, refs] of Object.entries(r.sqlVerbs || {})) {
      for (const ref of refs || []) {
        const mName = ref.$ref.split('/').pop();
        if (!r.methods[mName]) {
          fail(`[${alias}] ${rName}.sqlVerbs.${verbKey} references missing method ${mName}`);
        }
      }
    }
    // Selectable methods must project at least one column: resolve the
    // success response schema (through objectKey) and require properties.
    for (const ref of (r.sqlVerbs && r.sqlVerbs.select) || []) {
      const mName = ref.$ref.split('/').pop();
      const m = r.methods[mName];
      const op = resolveOperation(spec, m);
      const objectKey = m.response && m.response.objectKey;
      const responses = (op && op.responses) || {};
      const okKey = (m.response && m.response.openAPIDocKey) || '200';
      const content = (responses[okKey] && responses[okKey].content) || {};
      const ct = Object.keys(content)[0];
      let schema = ct ? derefSchema(spec, content[ct].schema) : null;
      if (schema && objectKey) {
        const key = objectKey.replace(/^\$\./, '');
        let node = derefSchema(spec, (schema.properties || {})[key]);
        if (node && node.type === 'array') node = derefSchema(spec, node.items);
        schema = node || null;
      }
      if (!(schema && schema.properties && Object.keys(schema.properties).length)) {
        fail(`[${alias}] ${rName}.${mName} is selectable but its row schema has no columns`);
      }
    }
  }

  try {
    verifySignatureUniqueness(spec, alias);
  } catch (err) {
    if (err.code === 'DUPLICATE_SIGNATURE') fail(err.message);
    throw err;
  }

  // ----- transform -----
  for (const [rName, r] of Object.entries(resources)) {
    r.id = `${provider}.${alias}.${rName}`;
    if (args['strip-schema-ref']) {
      for (const m of Object.values(r.methods || {})) {
        if (m.response && m.response.schemaRef) delete m.response.schemaRef;
      }
    }
  }

  const title = meta.title || (spec.info && spec.info.title) || alias;
  const description =
    meta.description || (spec.info && spec.info.description) || `${alias} API`;
  spec.info = spec.info || {};
  spec.info.title = title;
  spec.info.description = description;
  spec.info['x-stackql-supplemental'] = true;

  // ----- write service doc + patch provider.yaml -----
  const outPath = path.join(outputBase, provider, version, 'services', `${alias}.yaml`);
  dumpYaml(outPath, spec);

  providerYaml.providerServices = providerYaml.providerServices || {};
  providerYaml.providerServices[alias] = {
    id: `${alias}:${version}`,
    name: alias,
    preferred: true,
    service: { $ref: `${provider}/${version}/services/${alias}.yaml` },
    title,
    version,
    description,
  };

  const resourceCount = Object.keys(resources).length;
  const viewNote = viewCount ? `, ${viewCount} views` : '';
  console.log(`  ok    ${provider}/${alias}  (${resourceCount} resources${viewNote}) [supplemental]`);
  injected++;
}

// Re-emit patched provider.yaml files with providerServices keys sorted
// alphabetically (stage 2 emits alphabetical because it iterates sorted
// source files - keep the invariant).
for (const [provider, providerYaml] of Object.entries(providerYamlCache)) {
  const sorted = {};
  for (const k of Object.keys(providerYaml.providerServices).sort()) {
    sorted[k] = providerYaml.providerServices[k];
  }
  providerYaml.providerServices = sorted;
  dumpYaml(path.join(outputBase, provider, version, 'provider.yaml'), providerYaml);
}

console.log(`\nInjected ${injected} supplemental services into ${Object.keys(providerYamlCache).length} providers`);
